#!/usr/bin/env python3
"""news-image-20261123 entrypoint (Python 3.13, standard library only).

Copies the pre-rendered front-page image entry.png from this directory into
$MAKEFUN_OUTPUT_DIR/entry.png (default /output), then verifies the copy:
PNG signature, size at most 1 MiB, dimensions at most 1024x1024, and prints
its SHA-256. The copy is byte-identical on every run.
"""
import hashlib
import os
import struct
import sys

MAX_BYTES = 1048576
MAX_DIM = 1024
PNG_SIG = b"\x89PNG\r\n\x1a\n"
# Expected artefacts of the shipped entry.png (regenerated by generate.py).
EXPECTED_BYTES = 176960
EXPECTED_SHA256 = "7ca158edc7b3991714523c9372b4faece7321b4322ec98f3d02781212e00df7c"


def fail(msg):
    print("ERROR: " + msg, file=sys.stderr)
    raise SystemExit(1)


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    src = os.path.join(here, "entry.png")
    outdir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    dst = os.path.join(outdir, "entry.png")
    try:
        with open(src, "rb") as fh:
            data = fh.read()
    except OSError as exc:
        fail("cannot read %s: %s" % (src, exc))
    if len(data) > MAX_BYTES:
        fail("entry.png is %d bytes, over the 1 MiB limit" % len(data))
    if data[:8] != PNG_SIG:
        fail("entry.png does not start with the PNG signature")
    if len(data) < 33 or data[12:16] != b"IHDR":
        fail("entry.png has no IHDR chunk")
    width, height = struct.unpack(">II", data[16:24])
    if width > MAX_DIM or height > MAX_DIM:
        fail("entry.png is %dx%d, over the 1024x1024 limit" % (width, height))
    if width < 1 or height < 1:
        fail("entry.png has a zero dimension")
    digest = hashlib.sha256(data).hexdigest()
    if len(data) != EXPECTED_BYTES or digest != EXPECTED_SHA256:
        fail("entry.png does not match the shipped artefact "
             "(%d bytes, sha256 %s)" % (len(data), digest))
    os.makedirs(outdir, exist_ok=True)
    with open(dst, "wb") as fh:
        fh.write(data)
    print("published %s (%d bytes, %dx%d PNG)" % (dst, len(data), width, height))
    print("sha256 %s" % digest)
    print("verified against shipped artefact: OK")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
